interface Revision {
  revision: string;
  sequence: number;
  created: string;
  reason: string;
  current: boolean;
  parent: string | null;
}
interface Snapshot {
  revision: string;
  catalog: KnowledgeCatalog;
  history: Revision[];
}
interface Bridge {
  load(): Promise<{
    snapshot: Snapshot;
    identity: { version: string; source: string; sourceDirty: boolean };
    notices: string;
  }>;
  save(base: string, catalog: KnowledgeCatalog, imported: boolean): Promise<Snapshot>;
  restore(base: string, revision: string): Promise<Snapshot>;
  importCatalog(): Promise<KnowledgeCatalog | null>;
  exportCatalog(kind: "json" | "html"): Promise<boolean>;
  quit(dirty: boolean): Promise<boolean>;
  onQuit(handler: () => void): void;
  onHelp(handler: () => void): void;
  onClosing(handler: () => void): void;
  ready(success: boolean): Promise<void>;
}
declare global {
  interface Window {
    portalWorkspace?: Bridge;
  }
}

function element(id: string): HTMLElement {
  const found = document.getElementById(id);
  if (!found) throw new Error("Workspace control is missing.");
  return found;
}
function input(id: string): HTMLInputElement {
  const value = element(id);
  if (!(value instanceof HTMLInputElement)) throw new Error("Input control is missing.");
  return value;
}
function select(id: string): HTMLSelectElement {
  const value = element(id);
  if (!(value instanceof HTMLSelectElement)) throw new Error("Selection control is missing.");
  return value;
}
function textArea(id: string): HTMLTextAreaElement {
  const value = element(id);
  if (!(value instanceof HTMLTextAreaElement)) throw new Error("Text control is missing.");
  return value;
}
function node(tag: string, text: string): HTMLElement {
  const item = document.createElement(tag);
  item.textContent = text;
  return item;
}
function options(id: string, values: readonly { value: string; label: string }[], keep = "") {
  const control = select(id);
  control.replaceChildren(
    ...values.map((item) => {
      const option = document.createElement("option");
      option.value = item.value;
      option.textContent = item.label;
      return option;
    }),
  );
  if (values.some((item) => item.value === keep)) control.value = keep;
}
let saved: Snapshot,
  draft: KnowledgeCatalog,
  topicId: string | undefined,
  productId: string | undefined,
  busy = false,
  closing = false,
  imported = false;
const bridge = window.portalWorkspace;
const dirtyEditors = new Set<string>();
function allowApply(id: string): boolean {
  return (
    ![...dirtyEditors].some((item) => item !== id) ||
    confirm("Applying this form will discard unapplied fields in the other forms. Continue?")
  );
}
function changed() {
  return dirtyEditors.size > 0 || canonicalCatalog(draft) !== canonicalCatalog(saved.catalog);
}
function status(message: string) {
  element("workspace-status").textContent = message;
}
function error(message: string) {
  const target = element("workspace-error");
  target.textContent = message;
  target.hidden = !message;
}
function canResumeControls(): boolean {
  // The native closing callback may run while an asynchronous action is pending.
  return !closing;
}
async function action(operation: () => void | Promise<void>) {
  if (busy || closing) return;
  busy = true;
  // A returned asynchronous snapshot must not overwrite fields edited while it was pending.
  // Keep Quit available so the owner can request retained-work shutdown through the real host.
  const controls = [
    ...document.querySelectorAll<
      HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement | HTMLButtonElement
    >("input, select, textarea, button"),
  ].filter((control) => control.id !== "quit-workspace");
  const previous = controls.map((control) => control.disabled);
  controls.forEach((control) => {
    control.disabled = true;
  });
  error("");
  try {
    await operation();
  } catch (cause) {
    error(
      cause instanceof Error
        ? cause.message
        : "The operation was refused; saved data is unchanged.",
    );
  } finally {
    busy = false;
    if (canResumeControls())
      controls.forEach((control, index) => {
        control.disabled = previous[index] ?? true;
      });
  }
}
function product(): Product | undefined {
  return draft.products.find((item) => item.id === select("product-select").value);
}
function fillProduct() {
  dirtyEditors.clear();
  const selected = product();
  productId = selected?.id;
  input("product-id").value = selected?.id ?? "";
  input("product-id").readOnly = Boolean(selected);
  input("product-name").value = selected?.name ?? "";
  textArea("product-description").value = selected?.description ?? "";
  options("version-clone", [
    { value: "", label: "No topic copy" },
    ...(selected?.versions.map((v) => ({ value: v.version, label: v.version })) ?? []),
  ]);
  const edition =
    selected?.versions.find((v) => v.lifecycle === "current") ?? selected?.versions[0];
  input("version-value").value = edition?.version ?? "1.0";
  select("version-lifecycle").value = edition?.lifecycle ?? "current";
  input("version-release").value = edition?.released ?? new Date().toISOString().slice(0, 10);
  input("version-end").value = edition?.endOfSupport ?? "";
  const topics = draft.topics.filter((item) => item.productId === selected?.id);
  options(
    "topic-select",
    topics.map((item) => ({ value: item.id, label: `${item.version} · ${item.title}` })),
    topicId,
  );
  fillTopic();
}
function fillTopic() {
  const selected = draft.topics.find((item) => item.id === select("topic-select").value);
  topicId = selected?.id;
  input("topic-title").value = selected?.title ?? "";
  textArea("topic-summary").value = selected?.summary ?? "";
  textArea("topic-json").value = selected ? JSON.stringify(selected, null, 2) : "";
  dirtyEditors.delete("topic-form");
  preview(selected);
}
function renderSection(parent: HTMLElement, topic: TopicDocument) {
  parent.append(
    node("h3", topic.title),
    node("p", `${topic.productName} ${topic.version} · ${topic.lifecycle} · ${topic.contentType}`),
    node("p", topic.summary),
  );
  for (const section of topic.sections) {
    const part = node("section", "");
    part.append(node("h4", section.title));
    for (const line of section.paragraphs) part.append(node("p", line));
    if (section.steps) {
      const list = node("ol", "");
      for (const step of section.steps) list.append(node("li", step));
      part.append(list);
    }
    if (section.warning) {
      const warning = node("aside", "");
      warning.className = "workspace-warning";
      warning.append(
        node("strong", section.warning.level.toUpperCase()),
        node("p", `Condition: ${section.warning.condition}`),
        node("p", `Consequence: ${section.warning.consequence}`),
        node("p", `Avoidance: ${section.warning.avoidance}`),
      );
      part.append(warning);
    }
    if (section.code) part.append(node("pre", section.code));
    parent.append(part);
  }
  parent.append(
    node(
      "p",
      `Source assertion: ${topic.provenance.sourceId}, pages ${topic.provenance.pages.join(", ")}; SHA256 ${topic.provenance.checksum}`,
    ),
  );
}
function preview(topic: TopicDocument | undefined) {
  const area = element("topic-preview");
  area.replaceChildren(node("h2", "Exact draft preview"));
  if (topic) renderSection(area, topic);
  else area.append(node("p", "Select a topic or add one."));
}
function render() {
  options(
    "product-select",
    draft.products.map((item) => ({ value: item.id, label: item.name })),
    productId,
  );
  fillProduct();
  options("search-product", [
    { value: "", label: "All products" },
    ...draft.products.map((item) => ({ value: item.id, label: item.name })),
  ]);
  fillSearchVersions();
  const requests = comparisonRequests(draft.topics, draft.products);
  options(
    "compare-request",
    requests.map((item, index) => ({
      value: String(index),
      label: `${item.productId} · ${item.slug} · ${item.from} → ${item.to}`,
    })),
  );
  element("workspace-comparison").replaceChildren();
  element("workspace-results").replaceChildren();
  element("workspace-answer").replaceChildren();
  const history = element("revision-history");
  history.replaceChildren();
  for (const revision of saved.history) {
    const li = node(
      "li",
      `Revision ${revision.sequence} · ${revision.created} · ${revision.reason}${revision.current ? " · current" : ""}`,
    );
    li.append(node("code", revision.revision));
    if (bridge && !revision.current) {
      const button = node("button", "Restore as new revision") as HTMLButtonElement;
      button.type = "button";
      button.addEventListener("click", () => {
        void action(async () => {
          if (changed() && !confirm("Discard the unsaved draft and restore this saved revision?"))
            return;
          saved = await bridge.restore(saved.revision, revision.revision);
          draft = validateCatalog(saved.catalog);
          imported = false;
          render();
          status("Restored as a new saved revision.");
        });
      });
      li.append(button);
    }
    history.append(li);
  }
  status(
    `${draft.products.length} products · ${draft.topics.length} topics · ${changed() ? "Unsaved draft" : "Saved catalog"}${bridge ? ` · revision ${saved.history.find((r) => r.current)?.sequence ?? "?"}` : " · browser preview only"}`,
  );
}
function fillSearchVersions() {
  const id = select("search-product").value;
  const versions = [
    ...new Set(
      draft.products
        .filter((p) => !id || p.id === id)
        .flatMap((p) => p.versions.map((v) => v.version)),
    ),
  ];
  options("search-version", [
    { value: "", label: "All editions" },
    ...versions.map((v) => ({ value: v, label: v })),
  ]);
}

document.querySelectorAll<HTMLButtonElement>("[data-panel]").forEach((button) =>
  button.addEventListener("click", () => {
    const id = button.dataset["panel"];
    document.querySelectorAll<HTMLElement>(".workspace-panel").forEach((panel) => {
      panel.hidden = panel.id !== id;
    });
    document
      .querySelectorAll("[data-panel]")
      .forEach((tab) => tab.setAttribute("aria-pressed", String(tab === button)));
  }),
);
if (bridge) {
  // Native navigation stays on this catalog rather than silently showing the bundled starter site.
  document.addEventListener("click", (event) => {
    const anchor = event.target instanceof Element ? event.target.closest("a") : null;
    if (!anchor) return;
    event.preventDefault();
    const url = new URL(anchor.href);
    if (url.protocol === "portal:" && url.hostname === "workbench") {
      const panel = ["/search/", "/compare/"].includes(url.pathname)
        ? "research"
        : url.pathname === "/about/"
          ? "history"
          : "authoring";
      document.querySelector<HTMLButtonElement>(`[data-panel="${panel}"]`)?.click();
      if (url.hash === "#main-content") element("main-content").focus();
    } else
      status(
        "External navigation is disabled in the desktop workspace. Contact: github.com/JasonStys.",
      );
  });
}
select("product-select").addEventListener("change", () => {
  if (
    dirtyEditors.size > 0 &&
    !confirm("Discard unapplied editor fields and select another product?")
  ) {
    select("product-select").value = productId ?? "";
    return;
  }
  fillProduct();
});
select("topic-select").addEventListener("change", () => {
  if (
    dirtyEditors.size > 0 &&
    !confirm("Discard unapplied editor fields and select another topic?")
  ) {
    select("topic-select").value = topicId ?? "";
    return;
  }
  fillTopic();
});
for (const id of ["product-form", "version-form", "topic-form"]) {
  element(id).addEventListener("input", () => {
    dirtyEditors.add(id);
    status("Unapplied editor fields. Validate and apply the form before saving a revision.");
  });
}
select("search-product").addEventListener("change", fillSearchVersions);
element("new-product").addEventListener("click", () => {
  if (
    dirtyEditors.size > 0 &&
    !confirm("Discard unapplied editor fields and create a new product?")
  )
    return;
  productId = undefined;
  select("product-select").value = "";
  fillProduct();
  input("product-id").focus();
});
element("product-form").addEventListener("submit", (event) => {
  event.preventDefault();
  void action(() => {
    if (!allowApply("product-form")) return;
    const old = product();
    const item = {
      id: input("product-id").value,
      name: input("product-name").value,
      description: textArea("product-description").value,
      versions: old?.versions ?? [],
    };
    draft = applyProduct(draft, JSON.stringify(item), productId);
    productId = item.id;
    render();
  });
});
element("version-form").addEventListener("submit", (event) => {
  event.preventDefault();
  void action(() => {
    if (!allowApply("version-form")) return;
    const selected = product();
    if (!selected) throw new Error("Create a product first.");
    const end = input("version-end").value;
    draft = applyVersion(
      draft,
      selected.id,
      {
        version: input("version-value").value,
        lifecycle: select("version-lifecycle").value,
        released: input("version-release").value,
        ...(end ? { endOfSupport: end } : {}),
      },
      select("version-clone").value || undefined,
    );
    render();
  });
});
element("new-topic").addEventListener("click", () => {
  void action(() => {
    if (
      dirtyEditors.size > 0 &&
      !confirm("Discard unapplied editor fields and create a new topic?")
    )
      return;
    fillProduct();
    const selected = product();
    const version =
      selected?.versions.find((v) => v.lifecycle === "current") ?? selected?.versions[0];
    if (!selected || !version) throw new Error("Add a product edition first.");
    topicId = undefined;
    select("topic-select").value = "";
    const template = {
      id: `${selected.id}-new-topic-${version.version.replace(".", "-")}`,
      topicSlug: "new-topic",
      title: "New documentation topic",
      summary: "Describe this topic and the exact product edition to which it applies.",
      productId: selected.id,
      productName: selected.name,
      version: version.version,
      lifecycle: version.lifecycle,
      contentType: "task",
      identifiers: [],
      synonyms: [],
      updated: new Date().toISOString().slice(0, 10),
      visibility: "public",
      provenance: { sourceId: "owner-authored-draft", pages: [1], checksum: "0".repeat(64) },
      sections: [
        {
          id: "overview",
          title: "Overview",
          paragraphs: ["Replace this draft with reviewed source content before using it."],
        },
      ],
    };
    textArea("topic-json").value = JSON.stringify(template, null, 2);
    input("topic-title").value = template.title;
    textArea("topic-summary").value = template.summary;
    dirtyEditors.add("topic-form");
    preview(undefined);
    input("topic-title").focus();
  });
});
element("topic-form").addEventListener("submit", (event) => {
  event.preventDefault();
  void action(() => {
    if (!allowApply("topic-form")) return;
    const raw = parseCatalogJson(textArea("topic-json").value);
    if (!raw || typeof raw !== "object" || Array.isArray(raw))
      throw new Error("A topic object is required.");
    const value = {
      ...raw,
      title: input("topic-title").value,
      summary: textArea("topic-summary").value,
    };
    draft = applyTopic(draft, JSON.stringify(value), topicId);
    topicId = (value as TopicDocument).id;
    render();
  });
});
element("delete-topic").addEventListener("click", () => {
  void action(() => {
    if (!topicId) throw new Error("Select a saved draft topic.");
    if (!confirm("Remove this topic from the draft? Saved history remains available.")) return;
    draft = removeTopic(draft, topicId);
    topicId = undefined;
    render();
  });
});
element("save-catalog").addEventListener("click", () => {
  void action(async () => {
    if (!bridge) throw new Error("Install the native app to save durable revisions.");
    if (dirtyEditors.size > 0)
      throw new Error("Validate and apply the edited form before saving a revision.");
    saved = await bridge.save(saved.revision, draft, imported);
    draft = validateCatalog(saved.catalog);
    imported = false;
    render();
    status("Revision saved. Search and exports use the saved catalog.");
  });
});
element("import-catalog").addEventListener("click", () => {
  void action(async () => {
    if (!bridge) throw new Error("Use the native application to import an owner-selected file.");
    if (changed() && !confirm("Replace the unsaved draft with the selected imported catalog?"))
      return;
    const catalog = await bridge.importCatalog();
    if (catalog) {
      draft = validateCatalog(catalog);
      imported = true;
      productId = undefined;
      topicId = undefined;
      render();
      status("Imported and validated into the draft. Save revision to retain it.");
    }
  });
});
for (const [id, kind] of [
  ["export-catalog", "json"],
  ["export-html", "html"],
] as const)
  element(id).addEventListener("click", () => {
    void action(async () => {
      if (!bridge) throw new Error("Use the native application to export the saved catalog.");
      status(
        (await bridge.exportCatalog(kind))
          ? "Saved catalog exported; existing files were not overwritten."
          : "Export canceled; saved catalog is unchanged.",
      );
    });
  });
async function quit() {
  if (bridge) await bridge.quit(changed());
}
element("quit-workspace").addEventListener("click", () => {
  void quit();
});
bridge?.onHelp(() => {
  document.querySelector<HTMLButtonElement>('[data-panel="history"]')?.click();
});
bridge?.onClosing(() => {
  closing = true;
  status(
    "Finishing accepted local work before exit. This window and workspace remain owned until completion.",
  );
  document
    .querySelectorAll<
      HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement | HTMLButtonElement
    >("input, select, textarea, button")
    .forEach((control) => {
      control.disabled = true;
    });
});
bridge?.onQuit(() => {
  void quit();
});
element("workspace-search").addEventListener("submit", (event) => {
  event.preventDefault();
  void action(() => {
    const query = input("workspace-query").value,
      index = createSearchIndex(draft.topics.map(toSearchDocument));
    const p = select("search-product").value,
      v = select("search-version").value;
    const filters = { ...(p ? { productId: p } : {}), ...(v ? { version: v } : {}) };
    const found = search(index, query, filters);
    const answer = answerQuestion(index, query, filters);
    element("workspace-answer").textContent =
      answer.status === "answered"
        ? answer.text
        : "No sufficiently supported extractive answer. Review the matching sources.";
    const list = element("workspace-results");
    list.replaceChildren();
    for (const result of found) {
      const topic = draft.topics.find((t) => t.id === result.document.id);
      const item = node("li", "");
      const button = node(
        "button",
        `${result.document.productName} ${result.document.version} · ${result.document.title}`,
      ) as HTMLButtonElement;
      button.type = "button";
      button.addEventListener("click", () => {
        if (topic) {
          if (
            dirtyEditors.size > 0 &&
            !confirm("Discard unapplied editor fields and open this search result?")
          )
            return;
          productId = topic.productId;
          topicId = topic.id;
          render();
          document.querySelector<HTMLButtonElement>('[data-panel="authoring"]')?.click();
        }
      });
      item.append(button, node("p", result.document.summary));
      list.append(item);
    }
    if (!found.length) list.append(node("li", "No matching sources in these filters."));
  });
});
element("workspace-compare").addEventListener("submit", (event) => {
  event.preventDefault();
  void action(() => {
    const request = comparisonRequests(draft.topics, draft.products)[
      Number(select("compare-request").value)
    ];
    if (!request) throw new Error("Two known editions of a stable topic are required.");
    const result = compareTopics(draft.topics, draft.products, request),
      area = element("workspace-comparison");
    area.replaceChildren(node("h3", `${request.slug}: ${request.from} → ${request.to}`));
    for (const row of result.sections) {
      const section = node("section", "");
      section.append(node("h4", `${row.id} · ${row.status} · warning ${row.warningStatus}`));
      for (const [label, topic, value] of [
        [request.from, result.before, row.before],
        [request.to, result.after, row.after],
      ] as const) {
        section.append(node("strong", label));
        if (topic && value) renderSection(section, { ...topic, sections: [value] });
        else section.append(node("p", "Absent in this edition; no inference is made."));
      }
      area.append(section);
    }
  });
});

void action(async () => {
  const initial = validateCatalog(parseCatalogJson(element("starter-catalog").textContent));
  if (bridge) {
    const loaded = await bridge.load();
    saved = { ...loaded.snapshot, catalog: validateCatalog(loaded.snapshot.catalog) };
    element("workspace-mode").textContent =
      "Native owner-local workspace · no automatic upload or external requests";
    element("native-identity").textContent =
      `Version ${loaded.identity.version} · source ${loaded.identity.source}${loaded.identity.sourceDirty ? " · working-tree candidate" : ""} · unsigned portable application`;
    element("native-notices").textContent = loaded.notices;
  } else {
    saved = { revision: "preview", catalog: initial, history: [] };
    element("workspace-mode").textContent =
      "Browser preview: edits are temporary and are lost on reload. The downloadable native app provides durable revision history and file dialogs.";
  }
  draft = validateCatalog(saved.catalog);
  render();
  await bridge?.ready(true);
}).catch(() => {
  void bridge?.ready(false);
});
